import 'package:dart_style/dart_style.dart';

import 'tokens_model.dart';

/// The package the generated type styles name their bundled fonts under.
const String emberPackage = 'kaname_ember_ui';

/// Renders [tokens] as the source of `ember_tokens.dart`.
///
/// The whole file is built in memory and put in formatter output form with
/// `dart_style`, so `dart format` leaves the committed file unchanged.
String renderTokens(TokenSet tokens) {
  final buffer = StringBuffer()
    ..writeln(
      '// GENERATED by `kaname_tools tokens` from brand/tokens.json. '
      'Do not edit by hand:',
    )
    ..writeln('// edit the JSON and run `mise run tokens`.')
    ..writeln()
    ..writeln("import 'package:flutter/material.dart';")
    ..writeln();
  _colours(buffer, tokens.colours);
  _shadows(buffer, tokens.shadows);
  _types(buffer, tokens);
  _dimensions(
    buffer,
    'EmberRadius',
    'Corner radii. Pills are for controls; containers get soft corners.',
    tokens.radii,
    'radius',
  );
  _dimensions(
    buffer,
    'EmberSpace',
    'Spacing steps on a 4px rhythm with frequent half-steps.',
    tokens.spaces,
    'spacing step',
  );
  _dimensions(
    buffer,
    'EmberSize',
    'Fixed component and shell sizes.',
    tokens.sizes,
    'size',
  );
  _motion(buffer, tokens);
  return DartFormatter(languageVersion: DartFormatter.latestLanguageVersion)
      .format(buffer.toString());
}

String _num(num value) =>
    value == value.truncate() ? value.truncate().toString() : value.toString();

String _sentence(String text) {
  final trimmed = text.trim();
  return trimmed.endsWith('.') ? trimmed : '$trimmed.';
}

String _doc(String? description, String fallback) =>
    '/// ${_sentence(description ?? fallback)}';

void _colours(StringBuffer b, List<ColourRole> roles) {
  b
    ..writeln('/// The Ember colour roles: one name, two rooms.')
    ..writeln('///')
    ..writeln(
      '/// [EmberColors.dark] and [EmberColors.light] hold every role. '
      'Read the active room',
    )
    ..writeln(
      '/// with [EmberColors.of] once the theme installs the extension.',
    )
    ..writeln('@immutable')
    ..writeln('class EmberColors extends ThemeExtension<EmberColors> {')
    ..writeln('/// Creates a set of colour roles.')
    ..writeln('const EmberColors({');
  for (final role in roles) {
    b.writeln('required this.${role.id},');
  }
  b.writeln('});');
  for (final role in roles) {
    b
      ..writeln(_doc(role.description, 'The `${role.name}` colour role'))
      ..writeln('final Color ${role.id};');
  }
  for (final (room, getter) in <(String, TokenColour Function(ColourRole))>[
    ('dark', (r) => r.dark),
    ('light', (r) => r.light),
  ]) {
    b
      ..writeln('/// The $room room.')
      ..writeln('static const EmberColors $room = EmberColors(');
    for (final role in roles) {
      b.writeln('${role.id}: ${getter(role).source},');
    }
    b.writeln(');');
  }
  b
    ..writeln('/// The colour roles of the ambient theme.')
    ..writeln('///')
    ..writeln(
      '/// Throws a [FlutterError] saying the Ember theme is not installed',
    )
    ..writeln(
      '/// when the theme has no [EmberColors] extension; `EmberTheme` '
      'installs it.',
    )
    ..writeln('static EmberColors of(BuildContext context) {')
    ..writeln('return Theme.of(context).extension<EmberColors>() ??')
    ..writeln('(throw FlutterError(')
    ..writeln("'Ember theme is not installed: no EmberColors extension on '")
    ..writeln(
      "'the ambient Theme. Use EmberTheme.dark() or EmberTheme.light().',",
    )
    ..writeln('));')
    ..writeln('}')
    ..writeln('/// Every role by its token name, for example `ink-tertiary`.')
    ..writeln('Map<String, Color> get byRole => {');
  for (final role in roles) {
    b.writeln("'${role.name}': ${role.id},");
  }
  b
    ..writeln('};')
    ..writeln('@override')
    ..writeln('EmberColors copyWith({');
  for (final role in roles) {
    b.writeln('Color? ${role.id},');
  }
  b.writeln('}) => EmberColors(');
  for (final role in roles) {
    b.writeln('${role.id}: ${role.id} ?? this.${role.id},');
  }
  b
    ..writeln(');')
    ..writeln('@override')
    ..writeln(
      'EmberColors lerp(ThemeExtension<EmberColors>? other, double t) {',
    )
    ..writeln('if (other is! EmberColors) return this;')
    ..writeln('return EmberColors(');
  for (final role in roles) {
    b.writeln('${role.id}: Color.lerp(${role.id}, other.${role.id}, t)!,');
  }
  b
    ..writeln(');')
    ..writeln('}')
    ..writeln('}');
}

String _boxShadows(List<ShadowLayer> layers) => [
  for (final layer in layers)
    'BoxShadow(color: ${layer.colour.source}, '
        'offset: Offset(${_num(layer.x)}, ${_num(layer.y)}), '
        'blurRadius: ${_num(layer.blur)})',
].join(', ');

String _capital(String id) => '${id[0].toUpperCase()}${id.substring(1)}';

void _shadows(StringBuffer b, List<ShadowToken> shadows) {
  b
    ..writeln('/// Shadows exist only on floating layers.')
    ..writeln('abstract final class EmberShadows {');
  for (final shadow in shadows) {
    for (final (room, layers) in [
      ('dark', shadow.dark),
      ('light', shadow.light),
    ]) {
      b
        ..writeln(
          _doc(
            shadow.description == null
                ? null
                : '${_sentence(shadow.description!)} In the $room room',
            'The `${shadow.name}` shadow in the $room room',
          ),
        )
        ..writeln(
          'static const List<BoxShadow> ${shadow.id}${_capital(room)} = '
          '[${_boxShadows(layers)}];',
        );
    }
  }
  b.writeln('}');
}

void _types(StringBuffer b, TokenSet tokens) {
  b
    ..writeln(
      '/// Two voices: serif for content the user wrote, sans for the tool.',
    )
    ..writeln('///')
    ..writeln(
      '/// Styles name their bundled font as a package font, so an app needs '
      'no font',
    )
    ..writeln(
      '/// declaration. There is no mono type style: the kit\'s mono is a '
      'system font',
    )
    ..writeln(
      '/// stack, which Flutter web cannot use. The first code or source view '
      'adds a',
    )
    ..writeln('/// bundled mono font and its style, never the system stack.')
    ..writeln('abstract final class EmberType {')
    ..writeln('/// The package that bundles the fonts the styles name.')
    ..writeln("static const String package = '$emberPackage';");
  for (final font in tokens.fonts) {
    b
      ..writeln('/// The bundled `${font.name}` family.')
      ..writeln("static const String ${font.id} = '${font.family}';");
  }
  for (final type in tokens.types) {
    final serif = type.font.name == 'serif';
    b
      ..writeln(
        '/// The `${type.name}` type style: ${type.font.family}, '
        '${_num(type.size)}px, weight ${type.weight}.',
      )
      ..writeln('static const TextStyle ${type.id} = TextStyle(')
      ..writeln("fontFamily: '${type.font.family}',")
      ..writeln('package: package,')
      ..writeln('fontSize: ${_num(type.size)},')
      ..writeln('fontWeight: FontWeight.w${type.weight},')
      ..writeln(
        'fontVariations: [${[if (serif) "FontVariation('opsz', ${_num(type.size)})", "FontVariation('wght', ${type.weight})"].join(', ')}],',
      )
      ..writeln('height: ${_num(type.lineHeight)},');
    if (type.letterSpacing case final spacing?) {
      b.writeln('letterSpacing: ${_num(spacing)},');
    }
    if (type.tabularFigures) {
      b.writeln('fontFeatures: [FontFeature.tabularFigures()],');
    }
    b.writeln(');');
  }
  b.writeln('}');
}

void _dimensions(
  StringBuffer b,
  String className,
  String description,
  List<DimensionToken> tokens,
  String noun,
) {
  b
    ..writeln(_doc(description, ''))
    ..writeln('abstract final class $className {');
  for (final token in tokens) {
    b
      ..writeln(_doc(token.description, 'The `${token.name}` $noun'))
      ..writeln('static const double ${token.id} = ${_num(token.value)};');
  }
  b.writeln('}');
}

void _motion(StringBuffer b, TokenSet tokens) {
  b
    ..writeln(
      '/// The one motion family: panels slide, stretch and collapse. '
      'Nothing else animates.',
    )
    ..writeln('abstract final class EmberMotion {');
  for (final token in tokens.durations) {
    b
      ..writeln(_doc(token.description, 'The `${token.name}` duration'))
      ..writeln(
        'static const Duration ${token.id} = '
        'Duration(milliseconds: ${token.milliseconds});',
      );
  }
  for (final token in tokens.curves) {
    b
      ..writeln(_doc(token.description, 'The `${token.name}` curve'))
      ..writeln(
        'static const Curve ${token.id} = '
        'Cubic(${token.points.map(_num).join(', ')});',
      );
  }
  b.writeln('}');
}
